/* Verify the JS port of value_parse matches the Python version exactly
   over the real corpus. Run: node check_parity.js */
const fs = require('fs');
const path = require('path');

// load value_parse.js into this context
eval(fs.readFileSync(path.join(__dirname, 'value_parse.js'), 'utf8'));

const db = JSON.parse(fs.readFileSync(path.join(__dirname, 'data/insights.json'), 'utf8'));
const dps = db.items.data_points;

// Python reference output, generated by:
//   python3 -c "import json,sys; sys.path.insert(0,'pipeline'); from value_parse import parse_value; ..."
const ref = JSON.parse(fs.readFileSync('/tmp/py_parse_ref.json', 'utf8'));

let mismatch = 0;
const byFamJs = {}, byFamPy = {};
dps.forEach((x, i) => {
  const r = ValueParse.parse(x.value, x.unit);
  const p = ref[i];
  byFamJs[r.family] = (byFamJs[r.family] || 0) + 1;
  byFamPy[p.family] = (byFamPy[p.family] || 0) + 1;
  const same = (r.n === null && p.n === null) ||
    (r.n !== null && p.n !== null && Math.abs(r.n - p.n) < 1e-6 * Math.max(1, Math.abs(p.n)));
  if (!same || r.family !== p.family) {
    mismatch++;
    if (mismatch <= 15) {
      console.log(`MISMATCH #${i}: ${JSON.stringify(x.value)} / ${JSON.stringify(x.unit)}`);
      console.log(`   js: ${r.n} ${r.family}`);
      console.log(`   py: ${p.n} ${p.family}`);
    }
  }
});

console.log(`\ntotal: ${dps.length}, mismatches: ${mismatch}`);
console.log('\nfamily  js   py');
Object.keys(ValueParse.FAMILY_LABELS).forEach(f => {
  const a = byFamJs[f] || 0, b = byFamPy[f] || 0;
  console.log(`${f.padEnd(14)} ${String(a).padStart(3)}  ${String(b).padStart(3)}  ${a === b ? '' : '  <-- DIFF'}`);
});
process.exit(mismatch ? 1 : 0);
